/**
 * Writes `src/migrations.generated.ts`, which imports every migration (as text) and the journal so
 * they are embedded in a compiled binary. Run after `drizzle-kit generate` (`bun run db:generate`).
 */
import { readdir } from 'node:fs/promises';
import { join } from 'node:path';

const root = join(import.meta.dir, '..');
const files = (await readdir(join(root, 'migrations'))).filter((file) => file.endsWith('.sql')).sort();

export const source = [
  '// Generated by scripts/embed-migrations.ts. Do not edit.',
  '/// <reference path="./assets.d.ts" />',
  "import journal from '../migrations/meta/_journal.json' with { type: 'json' };",
  ...files.map((file, i) => `import m${i} from '../migrations/${file}' with { type: 'text' };`),
  '',
  '/** Every migration file, by name, plus the drizzle-kit journal. */',
  `export const migrations = { journal, files: { ${files.map((file, i) => `'${file}': m${i}`).join(', ')} } };`,
  '',
].join('\n');

if (import.meta.main) await Bun.write(join(root, 'src/migrations.generated.ts'), source);
